public class PresenceService
{
    private readonly Dictionary<Guid, DateTime> _lastSeen = new();
    private readonly Dictionary<Guid, HashSet<string>> _connections = new();

    public void UserConnected(Guid userId, string connectionId)
    {
        lock (_connections)
        {
            if (!_connections.ContainsKey(userId))
                _connections[userId] = new HashSet<string>();
            _connections[userId].Add(connectionId);
        }
    }

    public void UserDisconnected(Guid userId, string connectionId)
    {
        lock (_connections)
        {
            _connections[userId]?.Remove(connectionId);
            if (_connections[userId]?.Count == 0)
            {
                _connections.Remove(userId);
                _lastSeen[userId] = DateTime.UtcNow;
            }
        }
    }

    public bool IsOnline(Guid userId) => _connections.ContainsKey(userId);
}

public class TypingTracker
{
    private readonly Dictionary<(Guid, Guid), DateTime> _typing = new();

    public void SetTyping(Guid conversationId, Guid userId)
    {
        _typing[(conversationId, userId)] = DateTime.UtcNow;
    }

    public bool IsTyping(Guid conversationId, Guid userId)
    {
        return _typing.TryGetValue((conversationId, userId), out var time)
            && (DateTime.UtcNow - time).TotalSeconds < 3;
    }
}
